                .monospacedDigit()
                .foregroundStyle(.secondary)
        }
        .padding(.horizontal, 12)
        .padding(.top, 10)
        .padding(.bottom, 6)
    }
}

// MARK: - agent 状态行

/// agent 行：语义图标 + 名称 + tabular skill 数；hover 高亮；点击在 Finder 打开其 skill 根目录。
struct MenuBarAgentRow: View {
    let name: String
    let icon: String
    let skillCount: Int
    let targetDirectory: URL?

    @State private var hovering = false

    var body: some View {
        HStack(spacing: 8) {
            Image(systemName: icon)
                .font(.system(size: 12))
                .foregroundStyle(.secondary)
                .frame(width: 16)
            Text(name)
                .font(.system(size: 12))
                .lineLimit(1)
            Spacer()
            Text("\(skillCount)")
                .font(.system(size: 11))
                .monospacedDigit()
                .foregroundStyle(.secondary)
        }
        .padding(.horizontal, 12)
        .padding(.vertical, 5)
        .background(hovering ? Color(nsColor: .secondarySystemFill) : .clear)
        .contentShape(Rectangle())
        .onHover { hovering = $0 }
        .onTapGesture {
            guard let targetDirectory else { return }
            NSWorkspace.shared.activateFileViewerSelecting([targetDirectory])
        }
        .help("在 Finder 中打开该 agent 的 skills 目录")
    }
}

